class Solution {
public:
    vector<int> findIndices(vector<int>& nums, int id, int vd) {
        int n = nums.size();
        int mn = nums[0], mx = nums[0], mni = 0, mxi = 0;
        for (int j = id; j < n; ++j) {
            int i = j - id;
            if (nums[i] < mn) { mn = nums[i]; mni = i; }
            if (nums[i] > mx) { mx = nums[i]; mxi = i; }
            if (nums[j] - mx >= vd) return {mxi, j};
            if (mn - nums[j] >= vd) return {mni, j};
        }
        return {-1, -1};
    }
};

